import{_ as r,C as l,c as i,o as c,a3 as n,G as a,j as e,a as o}from"./chunks/framework.Dokpd4od.js";const C=JSON.parse('{"title":"Contacts","description":"","frontmatter":{},"headers":[],"relativePath":"master/getting-started/contacts/contacts.md","filePath":"master/getting-started/contacts/contacts.md","lastUpdated":1793074831000}'),d={name:"master/getting-started/contacts/contacts.md"};function g(h,t,m,p,u,f){const s=l("ImagePopup");return c(),i("div",null,[t[0]||(t[0]=n('<h1 id="contacts" tabindex="-1">Contacts <a class="header-anchor" href="#contacts" aria-label="Permalink to &quot;Contacts&quot;">​</a></h1><p>A contact is a person or a company you deal with. Customers, vendors and your own company are all contacts. Aureus keeps each contact once, with its phone, email, tax number and addresses. Other modules, such as Sales and Purchase, pick people from this list.</p><blockquote><p><strong>In simple words:</strong> Contacts is your address book. Add a person or a company once and use it everywhere.</p></blockquote><p>Open <code>Contacts → Contacts</code>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>The Contacts plugin must be installed. See <a href="./../../general-settings/plugins.html">Plugins</a>. Create <a href="./configurations.html">titles, tags and industries</a> first if you want to pick them on the form.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page opens on the contact list. Tabs filter it: <strong>Individuals</strong>, <strong>Companies</strong>, <strong>Employees</strong>, <strong>Customers</strong>, <strong>Vendors</strong> and <strong>Archived</strong>. The list shows one card per contact. A card shows the name, the company, the job title, the email, the phone and the tags. Use the search box to find a contact. Group the cards by <strong>Account Type</strong>, <strong>Company</strong>, <strong>Title</strong>, <strong>Job Title</strong> or <strong>Industry</strong>. The filter panel lets you narrow the list by fields such as <strong>Name</strong>, <strong>Email</strong>, <strong>Job Title</strong>, <strong>Website</strong> and <strong>Tax ID</strong>.</p><p>Each card has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>. A clock icon schedules an activity.</p><h2 id="create-a-contact" tabindex="-1">Create a contact <a class="header-anchor" href="#create-a-contact" aria-label="Permalink to &quot;Create a contact&quot;">​</a></h2><ol><li>Open <code>Contacts → Contacts</code> and click <strong>Create Contact</strong>.</li></ol>',10)),a(s,{src:"/images1/contacts/navigate_create_contact.png",alt:"Contacts menu with the Contacts list and the Create Contact button"}),t[1]||(t[1]=n('<ol start="2"><li>Fill in the <strong>General</strong> section.</li></ol><ul><li><strong><em>Individual or Company:</em></strong> Choose <strong>Company</strong> for a business. Choose <strong>Individual</strong> for a person. Only a person can belong to a company, so the <strong>Company</strong> field shows for <strong>Individual</strong>.</li><li><strong><em>Name:</em></strong> Required. The full name of the person or the business.</li><li><strong><em>Company:</em></strong> The business this person works for. Pick one, or create it from the field.</li><li><strong><em>Tax ID:</em></strong> The tax number of the contact, for example <code>29ABCDE1234F1Z5</code>.</li><li><strong><em>Job Title:</em></strong> The role of the person, for example <code>Purchase Manager</code>.</li><li><strong><em>Phone</em> and <em>Mobile:</em></strong> The office number and the direct number.</li><li><strong><em>Email</em> and <em>Website:</em></strong> How to reach the contact.</li><li><strong><em>Title:</em></strong> A prefix such as <code>Dr.</code> or <code>Mr.</code>. See <a href="./configurations.html">Configurations</a>.</li><li><strong><em>Tags:</em></strong> Labels such as <code>VIP</code> or <code>Supplier</code>. You can create a tag from the field.</li><li><strong><em>Address:</em></strong> Street, city, zip code, state and country.</li></ul>',2)),a(s,{src:"/images1/contacts/general_contact.png",alt:"General section of the contact form with name, tax ID, phone, email, title, tags and address"}),t[2]||(t[2]=n('<ol start="3"><li>Open the <strong>Sales and Purchases</strong> tab if you need it.</li></ol><ul><li><strong><em>Responsible:</em></strong> The user who looks after this contact, for example the account manager.</li><li><strong><em>Company ID:</em></strong> The registration number of the company, for example <code>CMP-0042</code>.</li><li><strong><em>Reference:</em></strong> Your own code for the contact, for example the ID in an old system.</li><li><strong><em>Industry:</em></strong> The business sector of the contact. See <a href="./configurations.html">Configurations</a>.</li></ul>',2)),a(s,{src:"/images1/contacts/others_contact.png",alt:"Sales and Purchases tab with Responsible, Company ID, Reference and Industry"}),t[3]||(t[3]=e("ol",{start:"4"},[e("li",null,[o("Click "),e("strong",null,"Create"),o(". Click "),e("strong",null,"Create & create another"),o(" to save and open a blank form. Click "),e("strong",null,"Cancel"),o(" to leave without saving.")])],-1)),t[4]||(t[4]=e("p",null,[o("Aureus opens the contact on its "),e("strong",null,"View"),o(" page.")],-1)),a(s,{src:"/images1/contacts/view_contact.png",alt:"View page of a contact with its details and the Contacts and Addresses tabs"}),t[5]||(t[5]=e("h2",{id:"add-people-to-a-company",tabindex:"-1"},[o("Add people to a company "),e("a",{class:"header-anchor",href:"#add-people-to-a-company","aria-label":'Permalink to "Add people to a company"'},"​")],-1)),t[6]||(t[6]=e("p",null,"A company often has several people you talk to. Add them to the company contact.",-1)),t[7]||(t[7]=e("ol",null,[e("li",null,[o("Open the company contact. Open its "),e("strong",null,"Contacts"),o(" tab.")]),e("li",null,[o("Click "),e("strong",null,"Add Contact"),o(". A window opens with the same fields as the main form.")]),e("li",null,"Fill in the person, for example a billing contact, and save.")],-1)),a(s,{src:"/images1/contacts/manage_contacts.png",alt:"Contacts tab of a company with the Add Contact window"}),t[8]||(t[8]=n('<h2 id="add-an-address" tabindex="-1">Add an address <a class="header-anchor" href="#add-an-address" aria-label="Permalink to &quot;Add an address&quot;">​</a></h2><p>A contact can have several addresses, for example one to bill and one to deliver to.</p><ol><li>Open the contact. Open its <strong>Addresses</strong> tab.</li><li>Click <strong>Add Address</strong>. The tab is called <strong>Addresses</strong>.</li><li>Choose the <strong>Types</strong> value: <strong>Permanent</strong>, <strong>Present</strong>, <strong>Invoice</strong>, <strong>Delivery</strong> or <strong>Other</strong>.</li><li>Fill in the name, email, phone, mobile and the full address. Save.</li></ol>',3)),a(s,{src:"/images1/contacts/address_tab.png",alt:"Addresses tab with the Add Address window and the address type list"}),t[9]||(t[9]=n('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Edit:</strong> opens the same form. Change values and click <strong>Save changes</strong>.</li><li><strong>Delete:</strong> archives the contact. It moves to the <strong>Archived</strong> tab.</li><li><strong>Restore:</strong> brings an archived contact back.</li><li><strong>Force delete:</strong> removes the contact for good. It fails if other records still use the contact.</li><li><strong>Chatter:</strong> the button on the <strong>View</strong> page. Use it for messages, notes and activities. See <a href="./../chatter.html">Chatter</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Force delete</strong> cannot be undone. Use <strong>Delete</strong> if you may need the contact again.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./configurations.html">Contacts configurations</a></li><li><a href="./../chatter.html">Chatter</a></li><li><a href="./../search-filter-group.html">Search, filter and group</a></li><li><a href="./../../general-settings/users/portal-access.html">Portal access</a></li></ul>',5))])}const _=r(d,[["render",g]]);export{C as __pageData,_ as default};
